-- C04 SNAPSHOT RESTORE — WRITES. Generated by build-and-verify.py; do not edit by hand.
-- Only on an explicit decision, and only if 00-optional-scoped-snapshot-writes.sql was run. One transaction.
-- Puts every promo that existed at snapshot time back to its snapshot values (re-inserting it if deleted) and makes
-- its target list equal to the snapshot. Promos created after the snapshot are left as they are. Sales, receipts and
-- every other table are untouched. Stops if the snapshot is missing or the live table shape changed since.
begin;
set local lock_timeout = '5s';
do $rs$
declare cols text;
begin
  if to_regclass('ops_backup.promos_pre_c04') is null or to_regclass('ops_backup.promo_items_pre_c04') is null then
    raise exception 'C04_SNAPSHOT_MISSING';
  end if;
  if (select string_agg(column_name || ':' || data_type, ',' order by ordinal_position) from information_schema.columns where table_schema = 'public' and table_name = 'promos') is distinct from (select string_agg(column_name || ':' || data_type, ',' order by ordinal_position) from information_schema.columns where table_schema = 'ops_backup' and table_name = 'promos_pre_c04')
  or (select string_agg(column_name || ':' || data_type, ',' order by ordinal_position) from information_schema.columns where table_schema = 'public' and table_name = 'promo_items') is distinct from (select string_agg(column_name || ':' || data_type, ',' order by ordinal_position) from information_schema.columns where table_schema = 'ops_backup' and table_name = 'promo_items_pre_c04') then
    raise exception 'C04_SNAPSHOT_SHAPE: live promo tables changed since the snapshot';
  end if;
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into cols
  from information_schema.columns where table_schema = 'public' and table_name = 'promos' and column_name <> 'id';
  execute format('update public.promos p set (%1$s) = (select %1$s from ops_backup.promos_pre_c04 s where s.id = p.id) '
                 'where p.id in (select id from ops_backup.promos_pre_c04)', cols);
  insert into public.promos select * from ops_backup.promos_pre_c04 s where not exists (select 1 from public.promos p where p.id = s.id);
  delete from public.promo_items i where i.promo_id in (select id from ops_backup.promos_pre_c04)
    and not exists (select 1 from ops_backup.promo_items_pre_c04 s where s.promo_id = i.promo_id and s.item_id = i.item_id);
  insert into public.promo_items select * from ops_backup.promo_items_pre_c04 s
    where not exists (select 1 from public.promo_items i where i.promo_id = s.promo_id and i.item_id = s.item_id);
end $rs$;
-- Proof (must be 0 / 0 / 0): snapshot promos that differ, snapshot targets missing, extra targets on snapshot promos.
select (select count(*) from ops_backup.promos_pre_c04 s left join public.promos p using (id) where to_jsonb(p) is distinct from to_jsonb(s)) as promos_differing,
  (select count(*) from ops_backup.promo_items_pre_c04 s where not exists (select 1 from public.promo_items i where i.promo_id = s.promo_id and i.item_id = s.item_id)) as targets_missing,
  (select count(*) from public.promo_items i where i.promo_id in (select id from ops_backup.promos_pre_c04)
     and not exists (select 1 from ops_backup.promo_items_pre_c04 s where s.promo_id = i.promo_id and s.item_id = i.item_id)) as targets_extra;
commit;
